{"source":"#include <stdio.h>

int fp(int a,int b)
{
    if(a<b)
        return a;
    return b;
}

int main(int argc, char *argv[])
{
    int n,m,a,b;
    scanf("%d %d %d %d",&n,&m,&a,&b);

    if(b >= a*m)
        printf("%d\n", n*a);
    else
    {
        printf("%d\n",(n/m)*b + fp((n%m)*a , b));
    }

    return 0;
}"}
